UPDATE "Entity" e SET summary=b.summary_es,content=b.essay_es FROM editorial_batch_006 b WHERE e.id=b.id;
UPDATE "EntityTranslation" t SET "shortDescription"=b.summary_es,essay=b.essay_es,excerpt=b.summary_es FROM editorial_batch_006 b WHERE t."entityId"=b.id AND t.locale='es';
INSERT INTO "EntityTranslation" (id,"entityId",locale,title,"shortDescription",essay,excerpt,"createdAt","updatedAt") SELECT 'batch006-'||b.id,b.id,'en',e.title,b.summary_en,b.essay_en,b.summary_en,now(),now() FROM editorial_batch_006 b JOIN "Entity" e ON e.id=b.id ON CONFLICT ("entityId",locale) DO UPDATE SET "shortDescription"=excluded."shortDescription",essay=excluded.essay,excerpt=excluded.excerpt,"updatedAt"=now();
UPDATE "Entity" e SET content=replace(e.content,chr(92)||'n',chr(10)) FROM editorial_batch_006 b WHERE e.id=b.id;
UPDATE "EntityTranslation" t SET essay=replace(t.essay,chr(92)||'n',chr(10)) WHERE t."entityId" IN (SELECT id FROM editorial_batch_006) AND t.locale IN ('es','en');
UPDATE "Entity" e SET content=regexp_replace(e.content,'\[\['||e.slug||'\|(.+?)\]\]','\1','g') FROM editorial_batch_006 b WHERE e.id=b.id;
UPDATE "EntityTranslation" t SET essay=regexp_replace(t.essay,'\[\['||e.slug||'\|(.+?)\]\]','\1','g') FROM editorial_batch_006 b JOIN "Entity" e ON e.id=b.id WHERE t."entityId"=b.id AND t.locale IN ('es','en');
COMMIT;
